# >>> CHOICES
# Channels currently configured for conda.
_choice_conda_channel() {
    conda config --show channels 2>/dev/null | awk '/^[[:space:]]*-[[:space:]]/ { print $2 }'
}

# Configuration keys from `conda config --show`.
_choice_conda_config_key() {
    conda config --show 2>/dev/null | awk -F: '/^[A-Za-z_][A-Za-z0-9_]*:/ { print $1 }'
}

# Environment names from `conda env list` (first column of non-comment rows).
_choice_conda_env() {
    conda env list 2>/dev/null | awk '!/^#/ && NF >= 2 { print $1 }'
}

# Installed conda plugin distribution names.
_choice_conda_plugin() {
    conda plugins list --json 2>/dev/null | jq -b -r '.[].name' 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
